    n, m = len(grid), len(grid[0])
    start = next(((r, c) for r in range(n) for c in range(m) if grid[r][c] == 2), None)
    if start is None:
        return out
    cr, cc = start
    parent = {start: None}
    queue = [start]
    end = None
    while queue:
        r, c = queue.pop(0)
        if (r, c) != start and (r == 0 or c == 0 or r == n-1 or c == m-1):
            end = (r, c)
            break
        for dr, dc in ((1,0), (0,1), (-1,0), (0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != 6 and (nr,nc) not in parent:
                parent[(nr,nc)] = (r,c)
                queue.append((nr,nc))
    if end is not None:
        p = end
        while p is not None:
            r, c = p
            if grid[r][c] == 9:
                out[r][c] = 7
            p = parent[p]
    walls = sum(cell == 6 for row in grid for cell in row)
    if not walls:
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 9:
                    out[r][c] = 7
    if walls < 30:
        for r in range(cr-1, cr+2):
            for c in range(cc-1, cc+2):
                if grid[r][c] == 3:
                    out[r][c] = 9
    else:
        out[cr-1][cc-1] = 9
        out[cr-1][cc] = 9
    return out
